arguments.new_str:
    // On Linux, set via: export MY_FLAG=""
    // .NET 9 breaking change: empty env vars are no longer treated as unset.
    // Environment.GetEnvironmentVariable("MY_FLAG") now returns "" instead of null.
    // Use a helper that distinguishes "not set" from "explicitly empty".
    var val = Environment.GetEnvironmentVariable("MY_FLAG");
    if (val == null && !IsEnvironmentVariableDefined("MY_FLAG"))
    {
        Console.WriteLine("MY_FLAG not set, using default");
    }
}

static bool IsEnvironmentVariableDefined(string name)
{
    // In .NET 9, GetEnvironmentVariable returns "" for export MY_FLAG="".
    // It returns null only when the variable is truly not set.
    return Environment.GetEnvironmentVariable(name) != null;
}

